import time
import jax
import jax.numpy as jnp
import tensorcircuit as tc
import optax

tc.set_backend('jax')
tc.set_dtype('complex64')
n=12
theta=0.31
dim=2**n

def make_init(which):
    c=tc.Circuit(n)
    if which==0:
        c.h(0)
        for i in range(n-1): c.cnot(i,i+1)
    elif which==1:
        for i in range(0,n,2):
            c.h(i); c.x(i+1); c.cnot(i,i+1)
    elif which==3:
        for i in range(n): c.h(i)
    psi=c.state()
    return jnp.outer(psi,jnp.conj(psi)).astype(jnp.complex64)

inits=jnp.stack([make_init(i) for i in range(4)])
U=jnp.asarray(tc.gates.rxx(theta=theta).tensor).reshape(4,4).astype(jnp.complex64)

def kraus_stack(p01,p10):
    k0=jnp.array([[jnp.sqrt(1-p01),0],[0,jnp.sqrt(1-p10)]],dtype=jnp.complex64)
    k1=jnp.array([[0,jnp.sqrt(p10)],[0,0]],dtype=jnp.complex64)
    k2=jnp.array([[0,0],[jnp.sqrt(p01),0]],dtype=jnp.complex64)
    return jnp.stack([k0,k1,k2])

def apply_2q_adj(dm, U, q):
    left=2**q; right=2**(n-q-2)
    rho=dm.reshape(left,4,right,left,4,right)
    # out = U rho U^dag
    rho=jnp.einsum('AB,xByzCw,DC->xAyzDw', U, rho, jnp.conj(U), optimize=True)
    return rho.reshape(dim,dim)

def apply_1q(dm, Ks, q):
    left=2**q; right=2**(n-q-1)
    rho=dm.reshape(left,2,right,left,2,right)
    # out = sum_K K rho K^dag
    # K: (A,a), rho (x,a,y,z,b,w), conjK (B,b)
    out = jnp.einsum('Kab,xayzbw,Kcb->xcyzcw', Ks, rho, jnp.conj(Ks), optimize=True)
    return out.reshape(dim,dim)

def evolve(dm, p01, p10):
    Ks=kraus_stack(p01,p10)
    for q in range(0,n,2):
        dm=apply_2q_adj(dm,U,q)
        dm=apply_1q(dm,Ks,q)
        dm=apply_1q(dm,Ks,q+1)
    for q in range(1,n-1,2):
        dm=apply_2q_adj(dm,U,q)
        dm=apply_1q(dm,Ks,q)
        dm=apply_1q(dm,Ks,q+1)
    return dm

def tc_ref(dm0,p01,p10):
