dref=tc_ref(inits[2],p01,p10)
d=evolve(inits[2],p01,p10)
print('diff', float(jnp.max(jnp.abs(dref-d))), flush=True)

def z_exps(dm):
    diag=jnp.real(jnp.diag(dm))
    idx=jnp.arange(dim)
    outs=[]
    for q in range(n):
        bit=(idx>>(n-1-q))&1
        outs.append(jnp.sum(diag*(1.0-2.0*bit.astype(jnp.float32))))
    bitsum=jnp.zeros(dim,dtype=jnp.int32)
