    outs.append(jnp.sum(diag*(1.0-2.0*(bitsum&1).astype(jnp.float32))))
    return jnp.stack(outs)

def table(p01,p10):
    dms=jax.vmap(lambda dm: evolve(dm,p01,p10))(inits)
    return jax.vmap(z_exps)(dms)

jt=jax.jit(table)
t0=time.time(); tab=jt(p01,p10); tab.block_until_ready(); print('t1', time.time()-t0, flush=True)
t0=time.time(); tab=jt(jnp.float32(0.07),jnp.float32(0.04)); tab.block_until_ready(); print('t2', time.time()-t0, tab.shape, flush=True)

# TC ref expectations
c=tc.DMCircuit(n,dminputs=inits[0])
ks=[kraus_stack(p01,p10)[i] for i in range(3)]
for q in range(0,n,2):
    c.rxx(q,q+1,theta=theta); c.general_kraus(ks,q); c.general_kraus(ks,q+1)
for q in range(1,n-1,2):
