ref=jnp.array([jnp.real(c.expectation_ps(z=[i])) for i in range(n)]+[jnp.real(c.expectation_ps(z=list(range(n))))])
print('ref', ref)
print('tab0', jt(p01,p10)[0])
print('max exp diff', float(jnp.max(jnp.abs(ref-jt(p01,p10)[0]))))
