import time
import itertools
import numpy as np
import jax
import jax.numpy as jnp
import tensorcircuit as tc

tc.set_backend('jax')
tc.set_dtype('complex128')  # better for int64 bit tricks if needed
n = 12
theta = 0.31

# Pauli basis matrices
I = np.eye(2, dtype=np.complex128)
X = np.array([[0,1],[1,0]], dtype=np.complex128)
Y = np.array([[0,-1j],[1j,0]], dtype=np.complex128)
Z = np.array([[1,0],[0,-1]], dtype=np.complex128)
PMS = [I,X,Y,Z]

def kraus_ops(p01, p10):
    K0 = np.array([[np.sqrt(1-p01),0],[0,np.sqrt(1-p10)]], dtype=np.complex128)
    K1 = np.array([[0,np.sqrt(p10)],[0,0]], dtype=np.complex128)
    K2 = np.array([[0,0],[np.sqrt(p01),0]], dtype=np.complex128)
    return [K0,K1,K2]

def dual_channel_ptm(p01, p10):
    """4x4 PTM for E*(P_j) = sum_i PTM[i,j] P_i in basis I,X,Y,Z. Columns map input basis."""
    Ks = kraus_ops(p01, p10)
    ptm = np.zeros((4,4), dtype=np.complex128)
