def dm_expectations(which, p01, p10):
    c = tc.DMCircuit(n)
    if which == 0:
        c.h(0)
        for i in range(n - 1):
            c.cnot(i, i + 1)
    elif which == 1:
        for i in range(0, n, 2):
            c.h(i)
            c.x(i + 1)
            c.cnot(i, i + 1)
    elif which == 3:
        for i in range(n):
            c.h(i)
    ks = [
        jnp.array(k, dtype=jnp.complex64) for k in kraus_ops(p01, p10)
    ]
    for q in range(0, n, 2):
        c.rxx(q, q + 1, theta=theta)
        c.general_kraus(ks, q)
        c.general_kraus(ks, q + 1)
    for q in range(1, n - 1, 2):
        c.rxx(q, q + 1, theta=theta)
        c.general_kraus(ks, q)
        c.general_kraus(ks, q + 1)
    ex = [float(np.real(c.expectation_ps(z=[i]))) for i in range(n)]
    ex.append(float(np.real(c.expectation_ps(z=list(range(n))))))
    return np.array(ex)

